  "implementation": "def solve(case):
    text = case["text"]
    passes = case["passes"]
    max_rounds = case["max_rounds"]
    applications = []
    fixed_point = False
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            old, new, name = p["old"], p["new"], p["name"]
            new_text = text.replace(old, new)
            if new_text != text:
                changed = True
                applications.append(name)
                text = new_text
        if not changed:
            fixed_point = True
            break
    return {"text": text, "fixed_point": fixed_point, "applications": applications}
